def edge(source,values,target,effect,speaker,line,scene='首次相关议题与后续回访',retro='目标未结案：重评可用路径；已结案：只追加新回应与合法补偿步骤，不回滚已执行选择。'):
    network['edges'].append({'id':f'X{len(network["edges"])+1:02}','source':source,'when':{f'resolve_{source}':values},'target':target,'effect':effect,'speaker':speaker,'line':line,'scene':scene,'retroactive':retro,'scope':'ending_committed之前可改未来意向；之后只影响地方履约与回应，不改N17快照。'})

