harmful={('N4','shift'),('N11','surrender'),('SQ03','retaliation'),('SQ04','sponsor')}
for qid,q in network['tasks'].items():
    for rt in q['routes']:
        rt['writes'].update(projections.get(qid,{}).get(rt['key'],{}))
        rt['requires']=['目标前置已满足','本路线现场核验完成','费用来源不同笔抵押','本路线所涉本人逐项同意或合法事前限定授权']
        rt['authorization_mode']='voluntary'
        if (qid,rt['key']) in harmful:
            rt['authorization_mode']='explicit_harm'
            rt['requires'][-1]='明示受影响者未同意及实际伤害后，玩家两步确认仍选择强制行为；绝不写受害者consent=true'
    q['entry']='地点可达即可先听需要；未满足原主线完成前置，只登记encountered与已见事实，不写完成、认证或奖励。'
    q['late']='后来的相关消息可以追加合法复核或补偿；不能改写已执行解法、删掉曾伤害、重生死者或重新领奖。'
    base=tasks[qid]
    if qid.startswith('DT'):
        q['default_dialogue']=[[base['speaker'],base['opening']]]
    else:
        first=base['scenes'][0]['lines']
        q['default_dialogue']=[next((ln for ln in first if ln[0]==q['speaker']),first[0])]
        base['outcome']='实际结案后按本页S62所选方法与分项处置生成回访；不得把S61旧选项的结果照抄。'+ '；'.join(r['label']+'：'+r['result'] for r in q['routes'])
        if qid.startswith('SQ'):
            base['reward']='A0.2B、B0.3B、C0.3B，各阶段只结算一次；赔付、运费与护理预算属于当事人，不返作玩家酬金。卖可选原件所得仅一次普通交易，不附加剧情赏；原封口/军功额外0.5B设计停用'
    if qid=='N6':
        next(rt for rt in q['routes'] if rt['key']=='witness')['dialogue'][0][0]='莉德'
